import re

_UNIT_EXPONENTS = {
    'b': 0,
    'kb': 1, 'kib': 1,
    'mb': 2, 'mib': 2,
    'gb': 3, 'gib': 3,
}

_PATTERN = re.compile(r'^\s*([+-]?\d+(?:\.\d+)?)\s*([a-zA-Z]+)\s*$')


def parse_size(text: str) -> int:
    if not isinstance(text, str):
        raise ValueError("input must be a string")

    stripped = text.strip()
    if not stripped:
        raise ValueError("input is empty or whitespace")

    match = _PATTERN.fullmatch(stripped)
    if match is None:
        raise ValueError(f"invalid size string: {text!r}")

    number_str, unit_str = match.groups()
    number = float(number_str)
    if number < 0:
        raise ValueError(f"size must be non-negative: {text!r}")

    unit_key = unit_str.lower()
    if unit_key not in _UNIT_EXPONENTS:
        raise ValueError(f"unknown unit: {unit_str!r}")

    base = 1024 if unit_key.endswith('ib') or unit_key == 'b' and False else 1000
    if unit_key.endswith('ib'):
        base = 1024
    elif unit_key == 'b':
        base = 1
    else:
        base = 1000

    value = number * (base ** _UNIT_EXPONENTS[unit_key])
    return int(round(value))
