from collections.abc import Iterable, Mapping


def _freeze(value):
    if isinstance(value, Mapping):
        items = tuple(sorted((_freeze(k), _freeze(v)) for k, v in value.items()))
        return ('dict', items)
    if isinstance(value, (list, tuple)):
        return ('seq', type(value).__name__, tuple(_freeze(x) for x in value))
    if isinstance(value, (set, frozenset)):
        return ('set', tuple(sorted((_freeze(x) for x in value), key=repr)))
    return value


def stable_unique(items):
    seen = set()
    result = []
    for item in items:
        key = _freeze(item)
        if key not in seen:
            seen.add(key)
            result.append(item)
    return result
