import json
import math


def parse_jsonl_metrics(lines: list[str]) -> dict:
    result = {"invalid": 0}
    service_data: dict[str, dict] = {}

    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        try:
            record = json.loads(stripped)
        except (json.JSONDecodeError, ValueError):
            result["invalid"] += 1
            continue

        if not isinstance(record, dict):
            result["invalid"] += 1
            continue

        service = record.get("service")
        latency_ms = record.get("latency_ms")
        status = record.get("status")

        if not isinstance(service, str):
            result["invalid"] += 1
            continue
        if not isinstance(latency_ms, (int, float)) or isinstance(latency_ms, bool):
            result["invalid"] += 1
            continue
        if not isinstance(status, (int, float)) or isinstance(status, bool):
            result["invalid"] += 1
            continue

        if service not in service_data:
            service_data[service] = {"latencies": [], "ok": 0, "count": 0}
        service_data[service]["latencies"].append(float(latency_ms))
        service_data[service]["count"] += 1
        if 200 <= status < 300:
            service_data[service]["ok"] += 1

    for service in sorted(service_data.keys()):
        data = service_data[service]
        n = data["count"]
        ok_rate = data["ok"] / n if n > 0 else 0.0
        sorted_latencies = sorted(data["latencies"])
        if n == 0:
            p95 = None
        else:
            idx = math.ceil(0.95 * n) - 1
            p95 = sorted_latencies[idx]
        result[service] = {"count": n, "ok_rate": ok_rate, "p95_latency_ms": p95}

    return result
