class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__(f"Cycle detected: {' -> '.join(cycle)}")
        self.cycle = cycle


def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set = set(nodes)
    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError(f"Unknown node in edge: ({a}, {b})")

    adjacency = {n: set() for n in nodes}
    in_degree = {n: 0 for n in nodes}
    unique_edges = set()

    for a, b in edges:
        if a == b:
            cycle = [a, a]
            raise CycleError(cycle)
        if (a, b) not in unique_edges:
            unique_edges.add((a, b))
            adjacency[a].add(b)
            in_degree[b] += 1

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in nodes}
    result = []
    available = sorted([n for n in nodes if in_degree[n] == 0])

    while available:
        available.sort()
        n = available.pop(0)
        result.append(n)
        color[n] = BLACK
        for m in sorted(adjacency[n]):
            in_degree[m] -= 1
            if in_degree[m] == 0 and color[m] == WHITE:
                available.append(m)

    if len(result) != len(nodes):
        # Find actual cycle using DFS
        cycle = _find_cycle(nodes, adjacency)
        raise CycleError(cycle)

    return result


def _find_cycle(nodes, adjacency):
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in nodes}
    parent = {}

    for start in sorted(nodes):
        if color[start] != WHITE:
            continue
        stack = [(start, iter(sorted(adjacency[start])))]
        color[start] = GRAY
        path = [start]
        while stack:
            node, children = stack[-1]
            try:
                child = next(children)
                if color[child] == GRAY:
                    idx = path.index(child)
                    return path[idx:] + [child]
                if color[child] == WHITE:
                    color[child] = GRAY
                    parent[child] = node
                    path.append(child)
                    stack.append((child, iter(sorted(adjacency[child]))))
            except StopIteration:
                color[node] = BLACK
                path.pop()
                stack.pop()
    return []
