from collections import defaultdict

def streaming_group_sum(rows):
    def gen():
        totals = defaultdict(float)
        order = []
        seen = set()
        for line in rows:
            try:
                parts = line if isinstance(line, (tuple, list)) else tuple(line)
                if len(parts) != 3:
                    gen.invalid_count += 1
                    continue
                _, key, value = parts
                if not isinstance(value, (int, float)) or isinstance(value, bool):
                    gen.invalid_count += 1
                    continue
                if key not in seen:
                    seen.add(key)
                    order.append(key)
                totals[key] += value
            except Exception:
                gen.invalid_count += 1
        for k in order:
            yield (k, totals[k])

    gen.invalid_count = 0
    return gen
