import time


def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    if attempts <= 0:
        raise ValueError("attempts must be > 0")
    last_exc = None
    for n in range(1, attempts + 1):
        try:
            return fn()
        except Exception as e:
            last_exc = e
            if n == attempts or not retry_if(e):
                raise
            sleep(base_delay * 2 ** (n - 1))
    raise last_exc
