from copy import deepcopy


def _get_parent(doc, path):
    keys = path.split('.')
    current = doc
    for key in keys[:-1]:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f'path not found: {path}')
    return current, keys[-1]


def apply_patch_ops(document: dict, operations) -> dict:
    new_doc = deepcopy(document)
    snapshot = deepcopy(new_doc)
    try:
        for op, path, value in operations:
            parent, key = _get_parent(new_doc, path)
            if not isinstance(parent, dict):
                raise TypeError(f'cannot apply {op} on non-dict at {path}')
            if op == 'set':
                parent[key] = value
            elif op == 'delete':
                parent.pop(key, None)
            elif op == 'increment':
                current = parent.get(key)
                if not isinstance(current, (int, float)) or isinstance(current, bool):
                    raise TypeError(f'increment requires numeric value at {path}, got {type(current).__name__}')
                if not isinstance(value, (int, float)) or isinstance(value, bool):
                    raise TypeError(f'increment value must be numeric, got {type(value).__name__}')
                parent[key] = current + value
            else:
                raise ValueError(f'unknown operation: {op}')
    except Exception:
        return snapshot
    return new_doc
