import time
from threading import RLock


class TTLCache:
    def __init__(self, maxsize: int, ttl: float, *, clock=time.time):
        if maxsize <= 0:
            raise ValueError("maxsize must be positive")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self._maxsize = maxsize
        self._ttl = float(ttl)
        self._clock = clock
        self._data = {}
        self._lock = RLock()

    def _is_expired(self, expiry):
        return self._clock() >= expiry

    def get(self, key, default=None):
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return default
            value, expiry = entry
            if self._is_expired(expiry):
                del self._data[key]
                return default
            self._data.pop(key, None)
            self._data[key] = (value, expiry)
            return value

    def set(self, key, value):
        with self._lock:
            expiry = self._clock() + self._ttl
            if key in self._data:
                self._data.pop(key, None)
            elif len(self._data) >= self._maxsize:
                self._evict()
            self._data[key] = (value, expiry)

    def delete(self, key):
        with self._lock:
            return self._data.pop(key, None) is not None

    def __len__(self):
        with self._lock:
            return len(self._data)

    def _evict(self):
        now = self._clock()
        for k in list(self._data.keys()):
            entry = self._data.get(k)
            if entry is not None and self._is_expired(entry[1]):
                self._data.pop(k, None)
                if len(self._data) < self._maxsize:
                    return
        if len(self._data) >= self._maxsize and self._data:
            oldest = next(iter(self._data))
            self._data.pop(oldest, None)
