import asyncio
from typing import Any, Callable, List, Tuple


async def run_with_deadline(
    coros: List[Callable[[], Any]],
    limit: int,
    timeout: float,
) -> List[Tuple[str, Any]]:
    results: List[Tuple[str, Any]] = [None] * len(coros)  # type: ignore
    pending: set = set()
    next_index = 0
    deadline_handle = asyncio.get_event_loop().call_later(timeout, lambda: None)

    async def run_one(idx: int, factory: Callable[[], Any]) -> None:
        try:
            value = await factory()
            results[idx] = ("ok", value)
        except asyncio.CancelledError:
            results[idx] = ("cancelled", None)
            raise
        except Exception as e:
            results[idx] = ("error", e)

    try:
        while next_index < len(coros):
            while len(pending) >= limit:
                done, pending = await asyncio.wait(
                    pending, return_when=asyncio.FIRST_COMPLETED
                )
                for d in done:
                    d.result()
            task = asyncio.create_task(run_one(next_index, coros[next_index]))
            pending.add(task)
            task.add_done_callback(pending.discard)
            next_index += 1

        if pending:
            done, pending = await asyncio.wait(
                pending, return_when=asyncio.FIRST_COMPLETED
            )
            for d in done:
                d.result()

        while pending:
            done, pending = await asyncio.wait(
                pending, return_when=asyncio.FIRST_COMPLETED
            )
            for d in done:
                d.result()
    finally:
        deadline_handle.cancel()
        if pending:
            for t in pending:
                t.cancel()
            final_done, _ = await asyncio.wait(pending)
            for d in final_done:
                try:
                    d.result()
                except (asyncio.CancelledError, Exception):
                    pass
            pending.clear()

    return results
