import threading
import collections


class BoundedQueue:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self._q = collections.deque()
        self._cap = capacity
        self._closed = False
        self._lock = threading.Condition(threading.Lock())

    def put(self, item):
        with self._lock:
            while len(self._q) >= self._cap and not self._closed:
                self._lock.wait()
            if self._closed:
                raise RuntimeError("queue is closed")
            self._q.append(item)
            self._lock.notify()

    def get(self):
        with self._lock:
            while len(self._q) == 0 and not self._closed:
                self._lock.wait()
            if not self._q:
                raise RuntimeError("queue is closed and empty")
            item = self._q.popleft()
            self._lock.notify()
            return item

    def close(self):
        with self._lock:
            if self._closed:
                return
            self._closed = True
            self._lock.notify_all()

    def qsize(self):
        with self._lock:
            return len(self._q)

    def is_closed(self):
        with self._lock:
            return self._closed
