import threading
from copy import deepcopy
from typing import Any, Dict, Optional


class VersionedStore:
    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._data: Dict[str, Any] = {}
        self._versions: Dict[str, int] = {}

    def read(self, key: str) -> Any:
        with self._lock:
            if key not in self._data:
                return None
            return deepcopy(self._data[key])

    def compare_and_set(
        self, key: str, expected_version: Optional[int], value: Any
    ) -> bool:
        with self._lock:
            current = self._versions.get(key, 0)
            if expected_version is None:
                if key in self._data:
                    return False
            else:
                if current != expected_version:
                    return False
            self._data[key] = deepcopy(value)
            self._versions[key] = current + 1
            return True

    def delete(self, key: str, expected_version: int) -> bool:
        with self._lock:
            if key not in self._data:
                return False
            if self._versions[key] != expected_version:
                return False
            del self._data[key]
            del self._versions[key]
            return True

    def snapshot(self) -> Dict[str, Any]:
        with self._lock:
            return {k: deepcopy(v) for k, v in self._data.items()}

    def get_version(self, key: str) -> int:
        with self._lock:
            return self._versions.get(key, 0)
